sort-bubble:
def sort_bubble(nums):
    a = list(nums)
    for end in range(len(a) - 1, 0, -1):
        swapped = False
        for i in range(end):
            if a[i] > a[i + 1]:
                a[i], a[i + 1] = a[i + 1], a[i]
                swapped = True
        if not swapped:
            break
    return a

sort-insertion:
def sort_insertion(nums):
    a = list(nums)
    for i in range(1, len(a)):
        key = a[i]
        j = i - 1
        while j >= 0 and a[j] > key:
            a[j + 1] = a[j]
            j -= 1
        a[j + 1] = key
    return a

sort-selection:
def sort_selection(nums):
    a = list(nums)
    for i in range(len(a) - 1):
        m = i
        for j in range(i + 1, len(a)):
            if a[j] < a[m]:
                m = j
        if m != i:
            a[i], a[m] = a[m], a[i]
    return a

sort-quick:
def sort_quick(nums):
    a = list(nums)

    def rec(lo, hi):
        if lo >= hi:
            return
        pivot = a[hi]
        i = lo
        for j in range(lo, hi):
            if a[j] < pivot:
                a[i], a[j] = a[j], a[i]
                i += 1
        a[i], a[hi] = a[hi], a[i]
        rec(lo, i - 1)
        rec(i + 1, hi)

    rec(0, len(a) - 1)
    return a

sort-merge:
def sort_merge(nums):
    def rec(a):
        if len(a) <= 1:
            return a
        mid = len(a) // 2
        left = rec(a[:mid])
        right = rec(a[mid:])
        out = []
        i = j = 0
        # 取等号时优先取左边，这就是归并稳定的原因
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                out.append(left[i]); i += 1
            else:
                out.append(right[j]); j += 1
        out.extend(left[i:])
        out.extend(right[j:])
        return out

    return rec(list(nums))

sort-counting:
def sort_counting(nums):
    if not nums:
        return []
    mx = max(nums)
    cnt = [0] * (mx + 1)
    for v in nums:
        cnt[v] += 1
    out = []
    for v in range(mx + 1):
        out.extend([v] * cnt[v])
    return out

sort-shell:
def sort_shell(nums):
    a = list(nums)
    gap = len(a) // 2
    while gap > 0:
        for i in range(gap, len(a)):
            key = a[i]
            j = i - gap
            while j >= 0 and a[j] > key:
                a[j + gap] = a[j]
                j -= gap
            a[j + gap] = key
        gap //= 2
    return a

sort-quickselect:
def sort_quickselect(nums, k):
    a = list(nums)
    target = len(a) - k          # "第 k 大"是名次，要换成升序下标
    lo, hi = 0, len(a) - 1
    while True:
        pivot = a[hi]
        i = lo
        for j in range(lo, hi):
            if a[j] < pivot:
                a[i], a[j] = a[j], a[i]
                i += 1
        a[i], a[hi] = a[hi], a[i]
        if i == target:
            return a[i]
        if i < target:
            lo = i + 1
        else:
            hi = i - 1

sort-radix:
def sort_radix(nums):
    a = list(nums)
    if not a:
        return a
    exp = 1
    while max(a) // exp > 0:
        buckets = [[] for _ in range(10)]
        for v in a:
            buckets[(v // exp) % 10].append(v)
        a = [v for b in buckets for v in b]     # 桶内保持原顺序 -> 稳定
        exp *= 10
    return a

bs-standard:
def bs_standard(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

