list-cycle:
def list_cycle(nums, cycle_at):
    if cycle_at < 0:
        return -1
    slow = fast = 0
    while True:
        slow = _cycle_next(slow, len(nums), cycle_at)
        fast = _cycle_next(_cycle_next(fast, len(nums), cycle_at), len(nums), cycle_at)
        if slow == -1 or fast == -1:
            return -1
        if slow == fast:
            break
    p = 0
    while p != slow:
        p = _cycle_next(p, len(nums), cycle_at)
        slow = _cycle_next(slow, len(nums), cycle_at)
    return p

