def st_two_stacks(spec):
    in_stack, out_stack, transfers = [], [], 0
    for op in spec.split(","):
        if op.startswith("push"):
            in_stack.append(int(op[4:]))
        else:
            if not out_stack:
                while in_stack:
                    out_stack.append(in_stack.pop()); transfers += 1
            if out_stack:
                out_stack.pop()
    return transfers

st-circle-queue:
def st_circle_queue(spec):
    n = 6
    buf = [None] * n
    head = tail = size = 0
    for op in spec.split(","):
        if op.startswith("enqueue"):
            if size == n:
                continue
            buf[tail] = int(op[7:])
            tail = (tail + 1) % n
            size += 1
        else:
            if size == 0:
                continue
            buf[head] = None
            head = (head + 1) % n
            size -= 1
    return [v for v in buf if v is not None]

