uf-union:
def uf_union(spec):
    parent = list(range(7))
    rank = [0] * 7
    unions = 0

    def find(x):
        r = x
        while parent[r] != r:
            r = parent[r]
        while parent[x] != r:
            parent[x], x = r, parent[x]
        return r

    for pair in (spec.split(",") if spec else []):
        a, b = (int(x) for x in pair.split("-"))
        ra, rb = find(a), find(b)
        if ra == rb:
            continue
        if rank[ra] < rank[rb]:
            parent[ra] = rb
        elif rank[ra] > rank[rb]:
            parent[rb] = ra
        else:
            parent[rb] = ra
            rank[ra] += 1
        unions += 1
    return unions

uf-find:
def uf_find(x):
    parent = list(range(7))
    for i in range(1, 7):
        parent[i] = i - 1          # 先造一条链
    r = x
    while parent[r] != r:
        r = parent[r]
    while parent[x] != r:
        parent[x], x = r, parent[x]
    return r

dp-knapsack:
def dp_knapsack(w, v, C):
    dp = [[0] * (C + 1) for _ in range(len(w) + 1)]
    for i in range(1, len(w) + 1):
        for c in range(C + 1):
            dp[i][c] = dp[i - 1][c]                      # 不装
            if c >= w[i - 1]:
                dp[i][c] = max(dp[i][c], dp[i - 1][c - w[i - 1]] + v[i - 1])
    return dp[len(w)][C]

dp-edit-distance:
def dp_edit_distance(a, b):
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j - 1], dp[i - 1][j], dp[i][j - 1])
    return dp[m][n]

