def dp_unbounded(w, v, C):
    dp = [[0] * (C + 1) for _ in range(len(w) + 1)]
    for i in range(1, len(w) + 1):
        for c in range(C + 1):
            dp[i][c] = dp[i - 1][c]
            if c >= w[i - 1]:
                # 注意是 dp[i][...]：同一行，表示这件还能再装
                dp[i][c] = max(dp[i][c], dp[i][c - w[i - 1]] + v[i - 1])
    return dp[len(w)][C]

