bt-nqueens:
def bt_nqueens(n):
    queens = [-1] * n

    def dfs(r):
        if r == n:
            return 1
        total = 0
        for c in range(n):
            if any(queens[rr] == c or abs(queens[rr] - c) == r - rr for rr in range(r)):
                continue                      # 剪枝：这一列放不了
            queens[r] = c
            total += dfs(r + 1)
            queens[r] = -1
        return total

    return dfs(0)

