graph-kruskal:
def graph_kruskal():
    parent = {n: n for n in _NODES}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    total, picked = 0, []
    for u, v, w in sorted(_EDGES, key=lambda e: e[2]):
        ru, rv = find(u), find(v)
        if ru == rv:
            continue
        parent[ru] = rv
        total += w
        picked.append("%s|%s" % (u, v) if u < v else "%s|%s" % (v, u))
        if len(picked) == len(_NODES) - 1:
            break
    return _mst_edges(total, picked)

graph-floyd:
def graph_floyd():
    n = len(_NODES)
    idx = {name: i for i, name in enumerate(_NODES)}
    INF = float("inf")
    d = [[INF] * n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0
    for u, v, w in _EDGES:
        i, j = idx[u], idx[v]
        d[i][j] = min(d[i][j], w)
        d[j][i] = min(d[j][i], w)
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if d[i][k] + d[k][j] < d[i][j]:
                    d[i][j] = d[i][k] + d[k][j]
    return ";".join("%s:%s" % (_NODES[i], "/".join(str(d[i][j]) for j in range(n))) for i in range(n))

graph-prim:
def graph_prim(start):
    inside = {start}
    total, picked = 0, []
    while len(inside) < len(_NODES):
        best = None
        for e in _EDGES:
            if (e[0] in inside) == (e[1] in inside):
                continue
            if best is None or e[2] < best[2]:
                best = e
        if best is None:
            break
        u, v, w = best
        inside.add(v if u in inside else u)
        total += w
        picked.append("%s|%s" % (u, v) if u < v else "%s|%s" % (v, u))
    return _mst_edges(total, picked)

graph-islands:
def graph_islands():
    g = [row[:] for row in _ISLAND_GRID]
    R, C = len(g), len(g[0])
    count = 0

    def flood(r, c):
        if r < 0 or r >= R or c < 0 or c >= C or g[r][c] != 1:
            return
        g[r][c] = 0
        flood(r + 1, c); flood(r - 1, c); flood(r, c + 1); flood(r, c - 1)

    for r in range(R):
        for c in range(C):
            if g[r][c] == 1:
                count += 1
                flood(r, c)
    return count

