    buckets = [[] for _ in range(N)]
    collisions = 0
    for key in nums:
        i = key % N
        if key in buckets[i]:
            continue
        if buckets[i]:
            collisions += 1
        buckets[i].append(key)
    return collisions, max(len(b) for b in buckets), sum(len(b) for b in buckets)

