    od = OrderedDict()
    for op in spec.split(","):
        kind, key = op[:3], int(op[3:])
        if kind == "get":
            if key not in od:
                continue
            od.move_to_end(key)
        else:
            val = key * 10
            if key in od:
                od.pop(key)
            elif len(od) == cap:
                od.popitem(last=False)      # 淘汰最久没用
            od[key] = val
    return list(reversed(list(od.keys())))

