def adv_segment_tree(nums, ql, qr):
    n = len(nums)
    tree = [0] * (4 * n)

    def build(node, l, r):
        if l == r:
            tree[node] = nums[l]
            return
        mid = (l + r) // 2
        build(node * 2, l, mid)
        build(node * 2 + 1, mid + 1, r)
        tree[node] = tree[node * 2] + tree[node * 2 + 1]

    def query(node, l, r):
        if qr < l or r < ql:
            return 0
        if ql <= l and r <= qr:
            return tree[node]
        mid = (l + r) // 2
        return query(node * 2, l, mid) + query(node * 2 + 1, mid + 1, r)

    build(1, 0, n - 1)
    return query(1, 0, n - 1)

