def lc_sort_list(vals):
    def sort(h):
        if h is None or h.next is None:
            return h
        slow, fast = h, h.next
        while fast and fast.next:
            slow = slow.next
            fast = fast.next.next
        mid = slow.next
        slow.next = None
        return merge(sort(h), sort(mid))

    def merge(a, b):
        dummy = _LNode(0)
        tail = dummy
        while a and b:
            if a.val <= b.val:
                tail.next = a; a = a.next
            else:
                tail.next = b; b = b.next
            tail = tail.next
        tail.next = a or b
        return dummy.next

    return _to_list(sort(_chain(vals)))

