lc-bst-lca:
def lc_bst_lca(levels, p, q):
    node = _build_tree3(levels)
    while node:
        if p < node.val and q < node.val:
            node = node.left
        elif p > node.val and q > node.val:
            node = node.right
        else:
            return node.val
    return -1

lc-sorted-to-bst:
def lc_sorted_to_bst(nums):
    def build(lo, hi):
        if lo > hi:
            return None
        mid = (lo + hi) // 2
        n = _TNode(nums[mid])
        n.left = build(lo, mid - 1)
        n.right = build(mid + 1, hi)
        return n

    root = build(0, len(nums) - 1)
    return _level_order(root)

lc-balanced:
def lc_balanced(levels):
    ok = [True]

    def depth(n):
        if n is None:
            return 0
        l, r = depth(n.left), depth(n.right)
        if abs(l - r) > 1:
            ok[0] = False
        return 1 + max(l, r)

    depth(_build_tree3(levels))
    return ok[0]

lc-min-depth:
def lc_min_depth(levels):
    def dfs(n):
        if n is None:
            return 0
        if n.left is None:
            return 1 + dfs(n.right)      # 只有一边孩子，不能算 0
        if n.right is None:
            return 1 + dfs(n.left)
        return 1 + min(dfs(n.left), dfs(n.right))

    return dfs(_build_tree3(levels))

lc-tree-paths:
def lc_tree_paths(levels):
    res = []

    def dfs(n, path):
        if n is None:
            return
        p = path + [str(n.val)]
        if n.left is None and n.right is None:
            res.append("->".join(p))
            return
        dfs(n.left, p)
        dfs(n.right, p)

    dfs(_build_tree3(levels), [])
    return len(res)

lc-right-view:
def lc_right_view(levels):
    root = _build_tree3(levels)
    if root is None:
        return []
    res = []
    q = [root]
    while q:
        res.append(q[-1].val)            # 每层最后一个
        nq = []
        for n in q:
            if n.left:
                nq.append(n.left)
            if n.right:
                nq.append(n.right)
        q = nq
    return res

lc-merge-trees:
def lc_merge_trees(a_levels, b_levels):
    def walk(x, y):
        if x is None:
            return y
        if y is None:
            return x
        x.val += y.val
        x.left = walk(x.left, y.left)
        x.right = walk(x.right, y.right)
        return x

    root = walk(_build_tree3(a_levels), _build_tree3(b_levels))
    return _level_order(root)

lc-kth-smallest:
def lc_kth_smallest(levels, k):
    st = []
    node = _build_tree3(levels)
    while node or st:
        while node:
            st.append(node)
            node = node.left
        node = st.pop()
        k -= 1
        if k == 0:
            return node.val
        node = node.right
    return -1

