def lc_ransom(ransom, mag):
    cnt = [0] * 26
    for ch in mag:
        cnt[ord(ch) - 97] += 1
    for ch in ransom:
        cnt[ord(ch) - 97] -= 1
        if cnt[ord(ch) - 97] < 0:
            return False
    return True

lc-rob-2:
def lc_rob_2(nums):
    def line(arr):
        prev = cur = 0
        for x in arr:
            prev, cur = cur, max(cur, prev + x)
        return cur

    if len(nums) == 1:
        return nums[0]
    # 首尾不能同时偷
    return max(line(nums[:-1]), line(nums[1:]))

lc-unique-paths-2:
def lc_unique_paths_2():
    g = _OBSTACLE_GRID
    m, n = len(g), len(g[0])
    dp = [[0] * n for _ in range(m)]
    for r in range(m):
        for c in range(n):
            if g[r][c] == 1:
                dp[r][c] = 0
            elif r == 0 and c == 0:
                dp[r][c] = 1
            else:
                up = dp[r - 1][c] if r else 0
                left = dp[r][c - 1] if c else 0
                dp[r][c] = up + left
    return dp[m - 1][n - 1]

lc-min-path-sum:
def lc_min_path_sum():
    g = _COST_GRID
    m, n = len(g), len(g[0])
    dp = [row[:] for row in g]
    for r in range(m):
        for c in range(n):
            if r == 0 and c == 0:
                continue
            up = dp[r - 1][c] if r else float("inf")
            left = dp[r][c - 1] if c else float("inf")
            dp[r][c] += min(up, left)
    return dp[m - 1][n - 1]

lc-lcs:
def lc_lcs(a, b):
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp[m][n]

